#!/bin/bash
# Generated by scripts/proxy-config.mjs in sirloinbh/project-standards from scripts/lib/signals.sh. Do not edit it on the server; regenerate and copy it (docs/runbooks/proxy.md).
# Server-wide AWS alert emitter (#1091, docs/research/uptime-gaps.md addendum). The AWS side judges: two CloudWatch metrics
# and one SNS topic. This script keeps the latest state of every signal on the server and sends the two numbers.
#   signals.sh record <app> <check> ok|fail   write the latest state of one signal (called by notify.sh and public-check.sh)
#   signals.sh evaluate                       judge all signals, send HeartbeatOk and FailingSignals, and publish to SNS
#                                             once when the set of failing signals changes (public-check.sh calls it every 5 minutes)
#   signals.sh status                         print every signal with its state and age (nothing is sent)
#   signals.sh call <service> <Field=value>...  one signed AWS query request (monitoring, sns or ses); the reusable helper
# A signal is failing when its last record is "fail", or "stale" when no record came within its limit: health and
# public 15 minutes, deploy 30 minutes, backup and report 26 hours, restore 8 days. The server judges only while it
# runs; the CloudWatch alarm on a missing HeartbeatOk covers a dead server (missing data counts as breaching).
# Server .env keys (__SHARED_ENV__, all needed only for the aws sink):
#   AWS_ALERT_ACCESS_KEY_ID, AWS_ALERT_SECRET_ACCESS_KEY   the alert IAM user (secret values; never printed)
#   AWS_ALERT_TOPIC_ARN                                    the SNS topic
#   AWS_ALERT_REGION                                       default ap-northeast-2
#   AWS_ALERT_NAMESPACE                                    default ProjectStandards/Uptime
# The SNS message holds signal names only, never a value from a log or an .env file.
set -uo pipefail

shared_env=${STANDARDS_ENV_FILE:-__SHARED_ENV__}
state=${SIGNALS_STATE_DIR:-/var/lib/project-standards/signals}

read_key() {
  [ -r "$shared_env" ] && sed -n "s/^$1=//p" "$shared_env" | tail -n 1 | tr -d "\"'\r"
}

now() { printf '%s' "${SIGNALS_NOW:-$(date +%s)}"; }

# Seconds without a record before a signal counts as stale.
max_age() {
  case "$1" in
    health | public) echo 900 ;;
    deploy) echo 1800 ;;
    restore) echo 691200 ;;
    *) echo 93600 ;;
  esac
}

# One signed request to CloudWatch ("monitoring"), SNS ("sns") or SES ("ses", host email). Fields are form fields. SigV4 is built into curl, so the server needs no
# AWS CLI, and the key pair goes to curl on standard input, never into the process list or the log (like the S3 upload in backup.sh).
aws_call() {
  local service=$1 id secret region
  shift
  id=$(read_key AWS_ALERT_ACCESS_KEY_ID || true)
  secret=$(read_key AWS_ALERT_SECRET_ACCESS_KEY || true)
  region=$(read_key AWS_ALERT_REGION || true)
  region=${region:-ap-northeast-2}
  if [ -z "$id" ] || [ -z "$secret" ]; then
    echo "AWS alerts are not configured: AWS_ALERT_ACCESS_KEY_ID or AWS_ALERT_SECRET_ACCESS_KEY is missing in $shared_env" >&2
    return 3
  fi
  local fields=() field host=$service
  [ "$service" = ses ] && host=email
  for field in "$@"; do fields+=(--data-urlencode "$field"); done
  printf 'user = "%s:%s"\n' "$id" "$secret" |
    curl -fsS -m 15 --retry 2 -K - --aws-sigv4 "aws:amz:$region:$service" -o /dev/null "${fields[@]}" "https://$host.$region.amazonaws.com/"
}

# Names of the failing signals, one per line, sorted. A stale one is written "<name> (stale)".
failing_signals() {
  local file name status ts age check
  for file in "$state"/*.*; do
    [ -f "$file" ] || continue
    name=$(basename "$file")
    read -r status ts < "$file" || continue
    check=${name##*.}
    age=$(($(now) - ${ts:-0}))
    if [ "$status" = fail ]; then
      echo "$name"
    elif [ "$age" -gt "$(max_age "$check")" ]; then
      echo "$name (stale)"
    fi
  done | sort
}

record() {
  local app=${1:-} check=${2:-} status=${3:-}
  if [[ ! "$app" =~ ^[a-z0-9-]+$ ]] || [[ ! "$check" =~ ^[a-z0-9-]+$ ]]; then
    echo "app and check must be lowercase letters, digits and hyphens" >&2
    return 2
  fi
  case "$status" in ok | fail) ;; *)
    echo "status must be ok or fail: $status" >&2
    return 2
    ;;
  esac
  mkdir -p "$state" || return 1
  printf '%s %s\n' "$status" "$(now)" > "$state/.$app.$check.tmp" && mv -f "$state/.$app.$check.tmp" "$state/$app.$check"
}

evaluate() {
  local list count namespace topic previous current rc=0 subject message
  list=$(failing_signals)
  count=$(printf '%s' "$list" | grep -c . || true)
  namespace=$(read_key AWS_ALERT_NAMESPACE || true)
  namespace=${namespace:-ProjectStandards/Uptime}

  # Both metrics in one call. HeartbeatOk is 1 on every run: the alarm treats missing data as breaching.
  if ! aws_call monitoring Action=PutMetricData Version=2010-08-01 "Namespace=$namespace" \
    MetricData.member.1.MetricName=HeartbeatOk MetricData.member.1.Value=1 MetricData.member.1.Unit=Count \
    MetricData.member.2.MetricName=FailingSignals "MetricData.member.2.Value=$count" MetricData.member.2.Unit=Count; then
    echo "could not send the CloudWatch metrics" >&2
    rc=1
  fi

  # One SNS message per change of the failing set. The state file moves only after a successful publish, so a failed one is retried.
  mkdir -p "$state" || return 1
  current=$(printf '%s' "$list" | paste -sd, - | sed 's/,/, /g')
  current=${current:-none}
  if [ -f "$state/.published" ]; then previous=$(cat "$state/.published"); else previous=none; fi
  if [ "$current" != "$previous" ]; then
    topic=$(read_key AWS_ALERT_TOPIC_ARN || true)
    if [ -z "$topic" ]; then
      echo "AWS_ALERT_TOPIC_ARN is missing in $shared_env; no SNS message was sent" >&2
      rc=1
    else
      if [ "$current" = none ]; then
        subject="Uptime recovered"
        message="All signals are ok again (was: $previous)."
      else
        subject="Uptime alert: $count failing"
        message="Failing signals: $current."
      fi
      if aws_call sns Action=Publish Version=2010-03-31 "TopicArn=$topic" "Subject=$subject" "Message=$message"; then
        printf '%s\n' "$current" > "$state/.published"
      else
        echo "could not publish to SNS" >&2
        rc=1
      fi
    fi
  fi
  # A first run with nothing failing saves that state without a message.
  [ -f "$state/.published" ] || [ "$current" != none ] || printf '%s\n' "$current" > "$state/.published"
  echo "signals: $count failing${list:+: $current}"
  return "$rc"
}

status() {
  local file name status ts
  for file in "$state"/*.*; do
    [ -f "$file" ] || continue
    name=$(basename "$file")
    read -r status ts < "$file" || continue
    echo "$name $status $(($(now) - ${ts:-0}))s ago"
  done
  echo "failing: $(failing_signals | paste -sd, - | sed 's/,/, /g')"
}

case "${1:-}" in
  record) shift; record "$@" ;;
  evaluate) evaluate ;;
  status) status ;;
  call) shift; aws_call "$@" ;;
  *)
    echo "usage: signals.sh record <app> <check> ok|fail | evaluate | status | call <service> <Field=value>..." >&2
    exit 2
    ;;
esac
